<?php
require_once __DIR__.'/../config/auth.php';
require_once __DIR__.'/../model/AdminModel.php';
require_admin();
$allowed=['categories','products','orders','feedback','users'];
$tab=in_array($_GET['tab']??'products',$allowed,true)?$_GET['tab']:'products';
$notice='';
try {
 if($_SERVER['REQUEST_METHOD']==='POST') {
  check_csrf();$action=$_POST['action']??'';$id=(int)($_POST['id']??0);
  if($action==='save_category') {
   $name=trim($_POST['name']??'');$slug=trim($_POST['slug']??'');$description=trim($_POST['description']??'');
   if(!$name||!preg_match('/^[a-z0-9-]+$/',$slug))throw new DomainException('Tên hoặc slug không hợp lệ');
   adminLuuDanhMuc($conn,$id,$name,$slug,$description);
  } elseif($action==='save_product') {
   $name=trim($_POST['name']??'');$cid=(int)($_POST['category_id']??0);$description=trim($_POST['description']??'');
   $price=(float)($_POST['price']??0);$stock=(int)($_POST['stock']??0);$image=trim($_POST['image_url']??'');
   if(!$name||$cid<1||$price<0||$stock<0||($image&&!filter_var($image,FILTER_VALIDATE_URL)))throw new DomainException('Thông tin sản phẩm không hợp lệ');
   adminLuuSanPham($conn,$id,$cid,$name,$description,$price,$image,$stock);
  } elseif($action==='delete_category') {adminXoaDanhMuc($conn,$id);}
  elseif($action==='delete_product') {adminAnSanPham($conn,$id);}
  elseif($action==='order_status') {
   $status=$_POST['status']??'';if(!in_array($status,['pending','confirmed','completed','cancelled'],true))throw new DomainException('Trạng thái không hợp lệ');
   adminCapNhatTrangThaiDon($conn,$status,$id);
  } else throw new DomainException('Tác vụ không hợp lệ');
  header('Location: index.php?tab='.urlencode($tab).'&saved=1');exit;
 }
} catch(Throwable $e){$notice=$e instanceof DomainException?$e->getMessage():'Không lưu được. Kiểm tra dữ liệu trùng hoặc mục đang được sử dụng.';}
$cats=adminLayDanhMuc($conn);
$products=adminLaySanPham($conn);
$orders=adminLayDonHang($conn);
$feedback=adminLayPhanHoi($conn);
$users=adminLayNguoiDung($conn);
$editId=(int)($_GET['edit']??0);$editing=null;
foreach($tab==='products'?$products:$cats as $r)if((int)$r['id']===$editId){$editing=$r;break;}
?><!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Starbucks Admin</title><style>
*{box-sizing:border-box}body{margin:0;background:#f5f8f5;color:#193b31;font:15px system-ui,Arial}header{background:#006241;color:white;padding:24px 5%}header a{color:white}main{max-width:1250px;margin:28px auto;padding:0 20px}nav{display:flex;gap:10px;flex-wrap:wrap;margin:20px 0}nav a{background:white;border-radius:10px;padding:11px 14px;color:#006241;text-decoration:none;border:1px solid #d7e4da}nav a.active{background:#006241;color:white}.card{background:white;padding:22px;border-radius:16px;margin:18px 0;box-shadow:0 3px 12px #15382914}table{border-collapse:collapse;width:100%}th,td{padding:12px;border-bottom:1px solid #e6eee8;text-align:left;vertical-align:top}th{background:#edf5ef}.scroll{overflow:auto}input,textarea,select{padding:10px;border:1px solid #b9cec0;border-radius:7px;width:100%}label{display:block;margin:10px 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px}button,.btn{background:#006241;color:white;border:0;border-radius:8px;padding:9px 13px;cursor:pointer;text-decoration:none;display:inline-block}.danger{background:#9e2b2b}.error{color:#a00000}form.inline{display:inline-block}form.inline button{margin:3px}.inline select{width:auto}img{max-width:65px;max-height:60px;border-radius:7px}small{color:#5a7063}
</style></head><body><header><h1>☕ Quản trị Starbucks</h1><div>Xin chào <?=h($_SESSION['user']['fullname'])?> · <a href="../view/cuahang.php">Xem cửa hàng</a></div></header><main><nav><?php foreach(['products'=>'Sản phẩm','categories'=>'Danh mục','orders'=>'Đơn hàng','feedback'=>'Phản hồi','users'=>'Tài khoản'] as $key=>$label):?><a class="<?=$tab===$key?'active':''?>" href="?tab=<?=h($key)?>"><?=h($label)?></a><?php endforeach;?></nav><?php if($notice):?><p class="error"><?=h($notice)?></p><?php elseif(isset($_GET['saved'])):?><p>✓ Đã cập nhật dữ liệu.</p><?php endif;?>
<?php if($tab==='categories'):?><section class="card"><h2><?=$editing?'Sửa':'Thêm'?> danh mục</h2><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="save_category"><input type="hidden" name="id" value="<?=h($editing['id']??0)?>"><div class="grid"><label>Tên<input required name="name" value="<?=h($editing['name']??'')?>"></label><label>Slug (không dấu, gạch ngang)<input required pattern="[a-z0-9-]+" name="slug" value="<?=h($editing['slug']??'')?>"></label></div><label>Mô tả<textarea name="description"><?=h($editing['description']??'')?></textarea></label><button>Lưu danh mục</button></form></section><div class="card scroll"><table><tr><th>ID</th><th>Tên</th><th>Slug</th><th>Thao tác</th></tr><?php foreach($cats as $c):?><tr><td><?=h($c['id'])?></td><td><?=h($c['name'])?></td><td><?=h($c['slug'])?></td><td><a class="btn" href="?tab=categories&edit=<?=$c['id']?>">Sửa</a> <form class="inline" method="post" onsubmit="return confirm('Xóa danh mục này?')"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="delete_category"><input type="hidden" name="id" value="<?=$c['id']?>"><button class="danger">Xóa</button></form></td></tr><?php endforeach;?></table></div>
<?php elseif($tab==='products'):?><section class="card"><h2><?=$editing?'Sửa':'Thêm'?> sản phẩm</h2><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="save_product"><input type="hidden" name="id" value="<?=h($editing['id']??0)?>"><div class="grid"><label>Tên<input name="name" required value="<?=h($editing['name']??'')?>"></label><label>Danh mục<select name="category_id" required><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=($editing['category_id']??0)==$c['id']?'selected':''?>><?=h($c['name'])?></option><?php endforeach;?></select></label><label>Giá (VNĐ)<input type="number" name="price" min="0" step="1000" required value="<?=h($editing['price']??0)?>"></label><label>Tồn kho<input type="number" name="stock" min="0" required value="<?=h($editing['stock']??100)?>"></label></div><label>URL hình ảnh<input name="image_url" type="url" value="<?=h($editing['image_url']??'')?>"></label><label>Mô tả<textarea name="description"><?=h($editing['description']??'')?></textarea></label><button>Lưu sản phẩm</button></form></section><div class="card scroll"><table><tr><th>ID</th><th>Hình</th><th>Tên</th><th>Danh mục</th><th>Giá</th><th>Kho</th><th>Thao tác</th></tr><?php foreach($products as $pr):?><tr><td><?=$pr['id']?></td><td><img src="<?=h($pr['image_url'])?>" alt=""></td><td><?=h($pr['name'])?></td><td><?=h($pr['category_name'])?></td><td><?=number_format((float)$pr['price'],0,',','.')?>đ</td><td><?=$pr['stock']?></td><td><a class="btn" href="?tab=products&edit=<?=$pr['id']?>">Sửa</a> <form class="inline" method="post" onsubmit="return confirm('Ẩn sản phẩm này khỏi cửa hàng?')"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="delete_product"><input type="hidden" name="id" value="<?=$pr['id']?>"><button class="danger">Ẩn</button></form></td></tr><?php endforeach;?></table></div>
<?php elseif($tab==='orders'):?><section class="card scroll"><h2>Đơn hàng mới nhất</h2><table><tr><th>Mã</th><th>Khách</th><th>Địa chỉ</th><th>Tổng</th><th>Thanh toán</th><th>Ngày</th><th>Trạng thái</th></tr><?php foreach($orders as $o):?><tr><td><?=h($o['code'])?></td><td><?=h($o['customer_name'])?><br><?=h($o['phone'])?></td><td><?=h($o['address'])?></td><td><?=number_format((float)$o['total'],0,',','.')?>đ</td><td><?=h($o['payment_method'])?></td><td><?=h($o['created_at'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="order_status"><input type="hidden" name="id" value="<?=$o['id']?>"><select name="status"><?php foreach(['pending'=>'Chờ xử lý','confirmed'=>'Đã xác nhận','completed'=>'Hoàn thành','cancelled'=>'Đã hủy'] as $k=>$v):?><option value="<?=$k?>" <?=$o['status']===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select><button>Lưu</button></form></td></tr><tr><td colspan="7"><small>Chi tiết: <?php foreach(adminLayChiTietDon($conn,(int)$o['id']) as $row)echo h($row['product_name']).' × '.h($row['quantity']).' ('.number_format((float)$row['price'],0,',','.').'đ); ';?></small></td></tr><?php endforeach;?></table></section>
<?php elseif($tab==='feedback'):?><section class="card scroll"><h2>Phản hồi</h2><table><tr><th>Ngày</th><th>Người gửi</th><th>Email</th><th>Nội dung</th></tr><?php foreach($feedback as $f):?><tr><td><?=h($f['created_at'])?></td><td><?=h($f['name'])?></td><td><?=h($f['email'])?></td><td><?=nl2br(h($f['message']))?></td></tr><?php endforeach;?></table></section>
<?php else:?><section class="card scroll"><h2>Danh sách tài khoản</h2><table><tr><th>ID</th><th>Họ tên</th><th>Email</th><th>Quyền</th><th>Ngày tạo</th></tr><?php foreach($users as $u):?><tr><td><?=$u['id']?></td><td><?=h($u['fullname'])?></td><td><?=h($u['email'])?></td><td><?=h($u['role'])?></td><td><?=h($u['created_at'])?></td></tr><?php endforeach;?></table></section><?php endif;?></main></body></html>
